// Indexed-pixel workbench data. Kept separate from engine-specific ROM adapters.
export const spriteId=()=>globalThis.crypto?.randomUUID?.()||'sprite-'+Date.now()+'-'+Math.random().toString(36).slice(2);
export const DEFAULT_PALETTE=['#000000','#202830','#506078','#98a8b8','#f8f8f8','#703838','#b85850','#f89078','#905828','#d89848','#f8d878','#386040','#60a060','#98d890','#4878b0','#88c8f0'];
export const VIEW_SIZES={front:[64,64,1],back:[64,64,1],icon:[32,32,2],overworld:[16,32,9],portrait:[64,64,1]};
export const VIEW_NAMES={front:'Front',back:'Back',icon:'Menu icon',overworld:'Overworld',portrait:'Portrait',item:'Item icon'};
export function studioData(project){return project.spriteStudio??={version:1,groups:[],palettes:[],drafts:{}};}
export function quantColour(hex){if(!/^#[0-9a-f]{6}$/i.test(hex))throw Error('Use a six-digit hex colour, such as #70a0d8.');return'#'+[1,3,5].map(i=>Math.round(Math.round(parseInt(hex.slice(i,i+2),16)*31/255)*255/31).toString(16).padStart(2,'0')).join('');}
export function makeSpriteGroup(name,{human=false,palette=DEFAULT_PALETTE,shiny=palette}={}){const roles=human?['portrait','overworld']:['front','back','icon','overworld'];return{id:spriteId(),name:String(name||'New sprite group').slice(0,80),kind:human?'character':'pokemon',normal:palette.map(quantColour),shiny:shiny.map(quantColour),views:Object.fromEntries(roles.map(role=>{const[w,h,count]=VIEW_SIZES[role];return[role,{width:w,height:h,frames:Array.from({length:count},()=>Array(w*h).fill(0))}];})),creature:{category:'new',parent:null,types:[1,1],stats:[50,50,50,50,50,50],abilities:[0,0,0],catchRate:45,baseExp:64,friendship:70,description:'',height:10,weight:100,learnset:[],evolutions:[],abilityDesigns:[]}};}
export function copyLayers(layers){return layers.map(l=>({...l,pixels:Array.from(l.pixels)}));}
export function mergeLayers(layers,size){const out=Array(size).fill(0),base=layers[0]?.pixels;for(const l of layers)if(l.visible!==false)for(let i=0;i<size;i++)if(l.pixels[i]&&(!l.clip||base?.[i]))out[i]=l.pixels[i];return out;}
export function drawPixelLine(pixels,width,height,a,b,colour,{size=1,mirror=false,clip=null}={}){let x=a.x,y=a.y,dx=Math.abs(b.x-x),dy=Math.abs(b.y-y),sx=x<b.x?1:-1,sy=y<b.y?1:-1,err=dx-dy;const dot=(xx,yy)=>{for(let y=yy-Math.floor((size-1)/2);y<yy+Math.ceil((size+1)/2);y++)for(let x=xx-Math.floor((size-1)/2);x<xx+Math.ceil((size+1)/2);x++)if(x>=0&&y>=0&&x<width&&y<height&&(!clip||clip[y*width+x]))pixels[y*width+x]=colour;};for(let i=0;i<width*height*2;i++){dot(x,y);if(mirror)dot(width-1-x,y);if(x===b.x&&y===b.y)break;const e=err*2;if(e>-dy){err-=dy;x+=sx;}if(e<dx){err+=dx;y+=sy;}}}
export function fillPixels(pixels,width,height,x,y,colour,clip=null){if(x<0||y<0||x>=width||y>=height)return;const from=pixels[y*width+x];if(from===colour)return;const todo=[y*width+x],seen=new Set();while(todo.length){const i=todo.pop();if(seen.has(i)||pixels[i]!==from||clip&&!clip[i])continue;seen.add(i);pixels[i]=colour;const x=i%width,y=Math.floor(i/width);if(x)todo.push(i-1);if(x<width-1)todo.push(i+1);if(y)todo.push(i-width);if(y<height-1)todo.push(i+width);}}
export function transformPixels(pixels,w,h,{flipX=false,flipY=false,dx=0,dy=0}={}){const out=Array(w*h).fill(0);for(let y=0;y<h;y++)for(let x=0;x<w;x++){const xx=(flipX?w-1-x:x)+dx,yy=(flipY?h-1-y:y)+dy;if(xx>=0&&yy>=0&&xx<w&&yy<h)out[yy*w+xx]=pixels[y*w+x];}return out;}
export function nearestPixels(pixels,sw,sh,w,h){return Array.from({length:w*h},(_,i)=>pixels[Math.min(sh-1,Math.floor(Math.floor(i/w)*sh/h))*sw+Math.min(sw-1,Math.floor(i%w*sw/w))]);}
export function indexRGBA(rgba,palette,{extract=false}={}){let colours=palette.map(quantColour);if(extract){const histogram=new Map();for(let i=0;i<rgba.length;i+=4)if(rgba[i+3]>=128){const c=quantColour('#'+Array.from(rgba.slice(i,i+3),n=>n.toString(16).padStart(2,'0')).join(''));histogram.set(c,(histogram.get(c)||0)+1);}const chosen=[...histogram].sort((a,b)=>b[1]-a[1]).slice(0,15).map(([c])=>c);colours=['#000000',...chosen];while(colours.length<16)colours.push('#000000');}const rgb=colours.map(c=>[1,3,5].map(i=>parseInt(c.slice(i,i+2),16))),cache=new Map();let mapped=0;const pixels=Array.from({length:rgba.length/4},(_,i)=>{if(rgba[i*4+3]<128)return 0;const k=rgba[i*4]+','+rgba[i*4+1]+','+rgba[i*4+2];if(cache.has(k))return cache.get(k);let best=1,distance=Infinity;for(let n=1;n<16;n++){const d=rgb[n].reduce((d,v,j)=>d+(v-rgba[i*4+j])**2,0);if(d<distance){best=n;distance=d;}}if(distance)mapped++;cache.set(k,best);return best;});return{pixels,palette:colours,mapped};}
export function paletteGPL(name,colours){return'GIMP Palette\nName: '+String(name).replace(/[\r\n]/g,' ')+'\nColumns: 8\n#\n'+colours.map((c,i)=>[1,3,5].map(k=>String(parseInt(c.slice(k,k+2),16)).padStart(3)).join(' ')+'\t'+(i===0?'Transparent':'Colour '+i)).join('\n')+'\n';}
export function readPaletteFile(text){if(text.startsWith('GIMP Palette')){const colors=text.split(/\r?\n/).filter(l=>/^\s*\d+\s+\d+\s+\d+/.test(l)).map(l=>'#'+l.trim().split(/\s+/).slice(0,3).map(n=>Math.min(255,+n).toString(16).padStart(2,'0')).join(''));if(colors.length!==16)throw Error('Use a 16-colour GIMP palette.');return{name:'Imported palette',normal:colors.map(quantColour)};}const v=JSON.parse(text),normal=v.normal||v.colours||v.palette;if(!Array.isArray(normal)||normal.length!==16)throw Error('Choose a saved 16-colour palette JSON or .gpl file.');return{name:String(v.name||'Imported palette').slice(0,80),normal:normal.map(quantColour),...(v.shiny?{shiny:(()=>{if(!Array.isArray(v.shiny)||v.shiny.length!==16)throw Error('A shiny palette needs 16 colours.');return v.shiny.map(quantColour);})()}:{})};}
export function validateSpriteStudio(project,assetIds=new Set()){const s=project.spriteStudio;if(s===undefined)return;if(!s||s.version!==1||!Array.isArray(s.groups)||s.groups.length>128||!Array.isArray(s.palettes)||s.palettes.length>256||!s.drafts||Array.isArray(s.drafts)||Object.keys(s.drafts).length>4096||JSON.stringify(s).length>32e6)throw Error('The sprite workspace is too large or invalid. Export groups separately.');const pal=p=>{if(!Array.isArray(p)||p.length!==16||p.some(c=>!/^#[a-f0-9]{6}$/i.test(c)))throw Error('A sprite palette needs 16 valid colours.');};const frame=(p,w,h)=>{if(!Array.isArray(p)||p.length!==w*h||p.some(n=>!Number.isInteger(n)||n<0||n>15))throw Error('A sprite frame has invalid palette indices.');};const dims=(w,h)=>{if(![w,h].every(n=>Number.isInteger(n)&&n>=8&&n<=128&&n%8===0))throw Error('Sprite dimensions must be multiples of 8, up to 128.');};const ids=new Set();for(const g of s.groups){if(typeof g.id!=='string'||ids.has(g.id)||typeof g.name!=='string'||g.name.length>80||!g.views||Object.keys(g.views).length>16)throw Error('A sprite group is invalid.');ids.add(g.id);pal(g.normal);pal(g.shiny);for(const v of Object.values(g.views)){dims(v.width,v.height);if(!Array.isArray(v.frames)||v.frames.length<1||v.frames.length>64)throw Error('A sprite view needs 1–64 frames.');for(const p of v.frames)frame(p,v.width,v.height);}}for(const p of s.palettes){pal(p.normal);if(p.shiny)pal(p.shiny);if(typeof p.name!=='string'||p.name.length>80)throw Error('A saved palette needs a name.');}for(const d of Object.values(s.drafts)){dims(d.width,d.height);if(!Array.isArray(d.layers)||d.layers.length<1||d.layers.length>8)throw Error('A sprite draft needs 1–8 layers.');for(const l of d.layers){if(typeof l.name!=='string'||l.name.length>80)throw Error('A sprite layer needs a valid name.');frame(l.pixels,d.width,d.height);}if(d.reference&&!assetIds.has(d.reference.assetId))throw Error('A sprite tracing reference is missing.');}if(s.abilities!==undefined&&(!Array.isArray(s.abilities)||s.abilities.length>256))throw Error('Too many custom ability designs.');}
